def _levenshtein_norm(source: str, target: str) -> float:
    """Calculates the normalized Levenshtein distance between two string
    arguments. The result will be a float in the range [0.0, 1.0], with 1.0
    signifying the biggest possible distance between strings with these lengths
    """
    # Compute Levenshtein distance using helper function. The max is always
    # just the length of the longer string, so this is used to normalize result
    # before returning it
    distance = _levenshtein(source, target)
    return float(distance) / max(len(source), len(target))


def _levenshtein(source: str, target: str) -> int:
    """Computes the Levenshtein
    (https://en.wikipedia.org/wiki/Levenshtein_distance)
    and edit distance between the provided source and target strings
    """
    # Create matrix of correct size (this is s_len + 1 * t_len + 1 so that the
    # empty prefixes "" + row of empty prefix and each prefix can be
    # represented). The matrix is initialized to the correct values for the
    # initial row and column (each distance from the empty prefix)
    s_len = len(source)
    t_len = len(target)
    matrix = [
        [
            max(a_index, b_index)  # Distance is just the length if one string is empty
            for a_index in range(s_len + 1)
        ]
        for b_index in range(t_len + 1)
    ]

    # Calculate each cell of the matrix using the Wagner-Fischer algorithm
    for b_index in range(1, t_len + 1):
        for a_index in range(1, s_len + 1):
            if source[a_index - 1] == target[b_index - 1]:
                matrix[b_index][a_index] = matrix[b_index - 1][a_index - 1]
            else:
                matrix[b_index][a_index] = min(
                    matrix[b_index - 1][a_index] + 1,
                    matrix[b_index][a_index - 1] + 1,
                    matrix[b_index - 1][a_index - 1] + 1,
                )

    # Return the bottom right corner of the matrix
    return matrix[t_len][s_len]


