                increment = [match.value]
            else:
                increment = match.value
            if isinstance(same_name[0].value, list) and isinstance(increment, list):
                same_name[0].value += increment
            return True, left_, collected
        elif not same_name and type(self.value) == list:
            if isinstance(match.value, str):
                match.value = [match.value]
            return True, left_, collected + [match]
        return True, left_, collected + [match]


class _BranchPattern(_Pattern):
    """Branch/inner node of a pattern tree."""

    def __init__(self, *children) -> None:
        self.children = list(children)

    def match(
        self, left: list[_Pattern], collected: Union[list[_Pattern], None] = None
    ) -> Any:
        raise NotImplementedError  # pragma: no cover

    def fix(self) -> _BranchPattern:
        self.fix_identities()
        self.fix_repeating_arguments()
        return self

    def fix_identities(self, uniq: Union[list, None] = None) -> None:
        """Make pattern-tree tips point to same object if they are equal."""
        flattened = self.flat()
        uniq = list(set(flattened)) if uniq is None else uniq
        for i, child in enumerate(self.children):
            if not hasattr(child, "children"):
                assert child in uniq
                self.children[i] = uniq[uniq.index(child)]
            else:
                child.fix_identities(uniq)

    def fix_repeating_arguments(self) -> _BranchPattern:
        """Fix elements that should accumulate/increment values."""
        either = [list(child.children) for child in _transform(self).children]
        for case in either:
            for e in [child for child in case if case.count(child) > 1]:
                if (
                    type(e) is _Argument
                    or type(e) is _Option
                    and e.argcount
                ):
                    if e.value is None:
                        e.value = []
                    elif type(e.value) is not list:
                        e.value = e.value.split()
                if type(e) is _Command or type(e) is _Option and e.argcount == 0:
                    e.value = 0
        return self

    def __repr__(self) -> str:
        return "%s(%s)" % (self.__class__.__name__, ", ".join(repr(a) for a in self.children))

    def flat(self, *types) -> Any:
        if type(self) in types:
            return [self]
        return sum([child.flat(*types) for child in self.children], [])
