class _DocSections(NamedTuple):
    before_usage: str
    usage_header: str
    usage_body: str
    after_usage: str


def _parse_docstring_sections(docstring: str) -> _DocSections:
    """Partition the docstring into the main sections.

    Returns a named tuple with the following structure:
    (text before usage, usage section header, indented usage body, text after usage)
    """
    usage_pattern = r"""
    # Any number of lines (that don't include usage:) precede the usage section
    \A(?P<before_usage>(?:(?!^usage:).*(?:\n|$))*?)
    # The `usage:` keyword is optionally preceded by whitespace
    ^(?P<usage_header>.*usage:)  # `.*` was added to support usage keywords that are indented
    (?P<usage_body>(?:\n(?:[ \t].*)?(?:\n|$))+?)
    # The usage pattern is terminated by a line that is not indented or the end of the string
    (?=^(?![ \t])|\Z)
    (?P<after_usage>(?:^(?:(?![ \t]).*)(?:\n|$))*)
    """
    match = re.match(usage_pattern, docstring, flags=re.M | re.I | re.VERBOSE)
    if not match:
        raise DocoptLanguageError(
            'Failed to parse doc: "usage:" section (case-insensitive) not found.'
        )
    return _DocSections(
        match.group("before_usage"),
        match.group("usage_header"),
        match.group("usage_body"),
        match.group("after_usage"),
    )
