```python
def _parse_docstring_sections(docstring: str) -> _DocSections:
    lines = docstring.splitlines(keepends=True)
    usage_line_idx = None
    for i, line in enumerate(lines):
        if re.search(r"usage:", line, flags=re.IGNORECASE):
            usage_line_idx = i
            break
    if usage_line_idx is None:
        raise DocoptLanguageError('"usage:" (case-insensitive) not found.')
    before = "".join(lines[:usage_line_idx])
    header_and_body = lines[usage_line_idx]
    m = re.match(r"^(.*?usage:)(.*)$", header_and_body, flags=re.IGNORECASE)
    header = m.group(1)
    body_lines = [m.group(2)]
    for line in lines[usage_line_idx + 1:]:
        if line.strip() == "" or line.startswith((" ", "\t")):
            body_lines.append(line)
        else:
            break
    body = "".join(body_lines)
    after = "".join(lines[usage_line_idx + len(body_lines):])
    return _DocSections(before, header, body, after)
```

