def _levenshtein(source: str, target: str) -> int:
    """Computes the Levenshtein distance between the source and target strings."""
    s_len = len(source)
    t_len = len(target)
    matrix = [
        [max(a_index, b_index) for a_index in range(s_len + 1)]
        for b_index in range(t_len + 1)
    ]
    for b_index in range(1, t_len + 1):
        for a_index in range(1, s_len + 1):
            if source[a_index - 1] == target[b_index - 1]:
                matrix[b_index][a_index] = matrix[b_index - 1][a_index - 1]
            else:
                matrix[b_index][a_index] = min(
                    matrix[b_index - 1][a_index] + 1,
                    matrix[b_index][a_index - 1] + 1,
                    matrix[b_index - 1][a_index - 1] + 1,
                )
    return matrix[t_len][s_len]


def _levenshtein_norm(source: str, target: str) -> float:
    """Calculates the normalized Levenshtein distance between two strings."""
    distance = _levenshtein(source, target)
    return float(distance) / max(len(source), len(target))
